import java.time.*;
interface Pass {boolean isValid(LocalDate date);boolean coversParkingFee();}
abstract class NewVehicle {final String regNo;NewVehicle(String r){regNo=r;}abstract double fee(int minutes,LocalTime in,LocalTime out);}
class EBike extends NewVehicle {final double flatFee;EBike(String r,double f){super(r);if(f<0)throw new IllegalArgumentException();flatFee=f;}double fee(int m,LocalTime i,LocalTime o){if(m<0)throw new IllegalArgumentException();return m==0?0:flatFee;}}
class DeliveryVan extends NewVehicle {DeliveryVan(String r){super(r);}double fee(int m,LocalTime in,LocalTime out){if(m<0)throw new IllegalArgumentException();long total=0;LocalDateTime start=LocalDateTime.of(LocalDate.now(),in),end=LocalDateTime.of(LocalDate.now(),out);if(end.isBefore(start))end=end.plusDays(1);for(LocalDateTime t=start;t.isBefore(end);t=t.plusMinutes(1)){boolean day=!t.toLocalTime().isBefore(LocalTime.of(9,0))&&t.toLocalTime().isBefore(LocalTime.of(17,0));total+=day?60:30;}return Math.ceil(total/60.0);}}
class OneDayPass implements Pass {private final LocalDate date;OneDayPass(LocalDate d){date=d;}public boolean isValid(LocalDate d){return date.equals(d);}public boolean coversParkingFee(){return true;}}
public class AdaptiveParkingDemo {public static void main(String[] args){NewVehicle b=new EBike("TN01EB1111",25),v=new DeliveryVan("TN02DV2222");System.out.println("E-bike fee: Rs "+b.fee(30,LocalTime.NOON,LocalTime.NOON));System.out.println("Delivery van fee: Rs "+v.fee(60,LocalTime.of(10,0),LocalTime.of(11,0)));System.out.println("One-day pass valid today: "+new OneDayPass(LocalDate.now()).isValid(LocalDate.now()));int[] slots={20,25,30,40,50};System.out.println("Floors: "+slots.length);}}